-- ============================================================
-- Azeroth: Эхо Пустоты (Azeroth Custom Realm)
-- 0064_rai_creature_template.sql  (acore_world)
--
-- Шаблоны существ RAI (Roaming Adventurer Incursions — странствующие
-- искатели). Порт RAI на mod-ale: RAI спавнит искателей динамически
-- через PerformIngameSpawn с entry, построенным как `100000 + level`
-- (см. raicreaturepicker.lua:ConstructCreatureEntry). Без шаблонов
-- PerformIngameSpawn не может создать существо.
--
-- Охват: уровни 5–60 -> entry 100005..100060 (56 шаблонов).
-- Плюс спавнер RAI entry 100100 (см. raiserver.lua, RegisterCreatureEvent
-- (100100, 5, ...) — «спавнящий» искателей по таймеру).
--
-- Конвенции:
--   * Диапазон 1000xx отделён от кастомных 70xxx (статические НПС
--     реалма) — это динамический пул RAI, формула 100000+level.
--   * minlevel = maxlevel = entry - 100000 (GetCreatureLevel читает
--     maxlevel для подбора спеллов/оружия, raidbhelper.lua).
--   * exp=0, faction 190 (гоблины, враждебные всем) — при спавне RAI
--     динамически меняет фракцию/модель (SetFaction/SetDisplayId/
--     SetEquipment в raispawner/raicreature), база не критична.
--   * AIName='' — боевые хуки вешаются событиями ALE по entry
--     (raiserver.lua RegisterCreatureEvent 5/1/2/9/4/24), скриптовый
--     AI не нужен, чтобы не конфликтовать с кастово-фазовым AI AIO.
--   * Модели задаются отдельно в creature_template_model (искатели
--     выглядят как игроки); RAI дополнительно подменяет модель при
--     спавне (raigenerator:SelectAdventurerDisplayID).
--   * Идемпотентно: DELETE+INSERT по entry.
-- ============================================================

DELETE FROM `creature_template` WHERE `entry` BETWEEN 100005 AND 100060;
DELETE FROM `creature_template` WHERE `entry` = 100100;

-- --- Искатели по уровням (100005..100060) ---
